const {Q,F}=require('../author.cjs');
const q=(id,los,stem,options,solution,section,pool='practice')=>Q('rea-'+id,'real-assets','alternatives',pool,los,stem,options,0,solution,{section});
const n=(id,los,stem,options,tex,reading,section,meaning,pool='practice')=>q(id,los,stem,options,[F(tex,reading,[['Z',meaning],...(tex.includes('\\sum')?[['t','Jahresindex der ausdrücklich datierten Zahlungsreihe.']]:[])])],section,pool);
module.exports=[
 q('01','a','Two office properties have the same floor area but different locations, tenant quality and remaining leases. A useful comparison should:',[['Adjust for these differences rather than assume identical assets.','Fläche allein vereinheitlicht weder Nachfrage noch Zahlungsrechte.'],['Use floor area as a sufficient measure of equal economic value.','Das lässt Standort und Mietverträge unberücksichtigt.'],['Treat every difference as a financing effect.','Die Merkmale können den Objektcashflow bereits vor Finanzierung verändern.']],['Immobilien sind heterogen; vergleichbare Transaktionen benötigen sachgerechte Anpassungen.'],'property-features'),
 q('02','a','A direct real estate investment differs from a small listed REIT holding primarily because the direct investment typically:',[['Requires more asset-specific management and a larger indivisible commitment.','Objektbetrieb und große Einzelposition liegen unmittelbarer beim Anleger.'],['Has a continuously executable exchange quotation.','Das kennzeichnet eher den börslichen Anteil.'],['Eliminates location concentration through legal ownership.','Ein Eigentumstitel streut den Standort nicht.']],['Verwaltung, Handelbarkeit und wirtschaftliche Risikostreuung sind eigene Dimensionen.'],'access'),
 q('03','a','A listed property share can be sold daily, while the underlying building cannot be sold quickly at low cost. This illustrates:',[['Liquidity of the security can differ from liquidity of its underlying assets.','Ein Anteil handelt separat vom Objekt.'],['Daily share trading makes property transaction costs disappear.','Börsenhandel ersetzt keinen kostenfreien Gebäudehandel.'],['An investor can always redeem the share for its appraised share of the building.','Ein gewöhnlicher Börsenkurs ist kein solches Rückgaberecht.']],['Die Börsenliquidität kann Zugang erleichtern, garantiert aber keinen Preis auf NAV-Höhe.'],'access'),
 q('04','a','A fully leased building with relatively stable operations is most consistent with a typical:',[['Core strategy.','Etablierter laufender Betrieb passt eher zur üblichen Core-Verwendung.'],['Ground-up development strategy.','Die wesentliche Bauentwicklung ist im Fall bereits erfolgt.'],['Distressed redevelopment by definition.','Problemlage und umfangreiche Umwandlung sind nicht gegeben.']],['Die Marktbezeichnung beschreibt ein typisches Profil und ersetzt keine konkrete Risikoprüfung.'],'strategies'),
 q('05','a','An investor buys a partly vacant building and plans substantial refurbishment and reletting. This is most consistent with:',[['A value-add approach with execution and leasing risk.','Umbau und Neuvermietung sind die wesentlichen Werttreiber.'],['Passive receipt of unchanged fully contracted cash flows.','Die zusätzlichen Erträge müssen erst durch Maßnahmen erreicht werden.'],['A debt claim secured by a completed building without operating exposure.','Der Fall bezeichnet eine Eigentumsstrategie mit operativen Aufgaben.']],['Ein höherer erwarteter NOI benötigt gegebenenfalls Investition, Zeit und erfolgreiche Durchführung.'],'strategies'),
 q('06','a','A long commercial lease is best assessed by examining:',[['Tenant credit, contractual rent terms, costs and the condition of the property.','Laufzeit wirkt zusammen mit Schuldner, Klauseln und Erhaltung.'],['Only the number of years until expiry.','Eine lange Laufzeit allein garantiert keine erhaltene Zahlung.'],['Only the tenant’s equity market return.','Das ersetzt weder Vertrags- noch Objektprüfung.']],['Vertragsrecht und tatsächliche Zahlungsfähigkeit müssen zusammenpassen.'],'leases'),
 n('07','a','A three-year lease pays zero at the end of year one and 120 at the end of each of years two and three. Its arithmetic annual rent average is:',[['80.00.','240 Gesamtmiete verteilt auf drei Jahre.'],['120.00.','Das ignoriert das erste mietfreie Jahr.'],['60.00.','Das würde auf vier statt drei Jahre verteilen.']],'Z=(0+120+120)/3=80','Der Durchschnitt ist kein Nachweis drei tatsächlich gleicher Cashzahlungen.','leases','Arithmetischer Mietdurchschnitt, WE pro Jahr.'),
 n('08','a','The same lease pays 120 only at the ends of years two and three. At an annual discount rate of 8%, the present value is closest to:',[['198.140527.','Beide Zahlungen werden zu ihren wirklichen späteren Terminen diskontiert.'],['213.991770.','Das verschiebt beide Zahlungen um ein Jahr nach vorn.'],['240.000000.','Das ignoriert den Zeitwert.']],'Z=120/(1{,}08)^2+120/(1{,}08)^3\\approx198{,}140527','Der erste Zahlungstermin ist Ende Jahr zwei, nicht Ende Jahr eins.','leases','Heutiger Wert der bezeichneten Mietzahlungen, WE.'),
 q('09','a','Which cost is ordinarily part of property operating expenses when computing NOI?', [['Property insurance for the operating building.','Eine laufende objektbezogene Versicherung ist Betriebskostenbestandteil.'],['Repayment of mortgage principal.','Tilgung gehört zur Finanzierung nach NOI.'],['A major separately capitalized roof replacement.','Diese zusätzliche Kapitalausgabe wird nicht nochmals als laufende NOI-Kosten unterstellt.']],['Die konkrete Abgrenzung wird geprüft; NOI schließt Finanzierung und Capex aus.'],'noi'),
 n('10','a','Potential rent is 1000, vacancy and collection loss 10%, other property revenue 20 and operating expenses 320. NOI is:',[['600.00.','900 Mietcash plus 20 sonstiger Ertrag minus 320 Kosten.'],['700.00.','Das ignoriert Leerstand und Ausfall.'],['920.00.','Das ist effektiver Bruttoertrag vor operativen Kosten.']],'Z=1000(1-0{,}10)+20-320=600','Zuerst werden tatsächliche Ertragsausfälle, dann laufende Objektkosten berücksichtigt.','noi','Jährlicher Objekt-NOI, WE.'),
 q('11','a','A mortgage REIT and an equity REIT most directly differ in their typical exposure to:',[['Property financing claims versus ownership and operation of properties.','Kreditanspruch und Objekteigentum erzeugen unterschiedliche Zahlungs- und Risikostrukturen.'],['Domestic versus foreign currency by definition.','Diese Unterscheidung folgt nicht aus den Bezeichnungen.'],['Listed versus necessarily unlisted legal status.','Beide Begriffe beschreiben nicht diese Börsenaufteilung.']],['Struktur und konkrete Bilanz sind zu prüfen, bevor Kennzahlen verglichen werden.'],'reit'),
 q('12','a','A property loses tenant demand because its technical layout is no longer suitable. This is an example of:',[['Functional obsolescence affecting future cash flows and possible reinvestment.','Die Nutzbarkeit kann trotz physischem Fortbestand sinken.'],['Proof that all remaining rent is risk-free.','Die veränderte Nachfrage kann Mieten und Leerstand belasten.'],['A change confined to depreciation entries with no possible economic effect.','Der Verlust kann reale Zahlungen und Umbauaufwand verändern.']],['Technischer Zustand und wirtschaftliche Eignung sind getrennt zu untersuchen.'],'property-limits'),
 q('13','a','A fixed geographic location most directly exposes a property investor to:',[['Changes in local demand and surrounding economic conditions.','Der Standort kann nicht mit veränderter Nachfrage einfach mitwandern.'],['Only nationwide average rent growth.','Lokale Märkte können davon stark abweichen.'],['Identical risk across all buildings in the country.','Standort, Nutzung und Mietverträge unterscheiden sich.']],['Nationale Kennzahlen ersetzen keine lokale Marktanalyse.'],'property-features'),
 q('14','a','A private property fund’s less frequent valuations most directly imply that:',[['Reported prices may incorporate market changes more slowly than listed prices.','Bewertungsintervalle können Informationen zeitlich verzögern.'],['Its economic volatility must be lower than that of all listed assets.','Glättung belegt keine geringeren tatsächlichen Risiken.'],['Every reported NAV is an immediately executable liquidation price.','Ein geschätzter NAV ist keine laufende Verkaufszusage.']],['Informationszeitpunkt und Liquidierbarkeit werden von der rechnerischen Renditestreuung getrennt.'],'property-limits'),
 n('15','a','A property reports accrued rental income 120, but receives cash rent 100. Cash operating costs are 40 and separate capex is 10. Cash available before financing is:',[['50.00.','100 erhaltenes Mietcash minus 40 laufende Kosten und zehn Capex.'],['80.00.','Das ist der vereinfachte periodisierte NOI vor Capex und Forderungsbewegung.'],['70.00.','Das verwendet ausgewiesene statt erhaltene Miete.']],'Z=100-40-10=50','Die Forderung von zwanzig ist noch kein erhaltenes Geld; Capex bindet weitere zehn.','tenant-credit','Tatsächlicher ungehebelter Cashflow im Jahr, WE.'),
 q('16','a','A property fund offers diversification across buildings, but has a concentrated single tenant across those buildings. The best conclusion is:',[['Common tenant credit can limit the apparent diversification.','Mehrere Gebäude beseitigen den gemeinsamen Schuldner nicht.'],['Building count alone eliminates tenant risk.','Die Ertragsquellen können wirtschaftlich stark zusammenhängen.'],['Tenant concentration affects only transaction fees.','Ein Mieterausfall kann laufende Erträge und Anschlussvermietung treffen.']],['Diversifikation wird nach Risikotreibern und nicht nur nach Objektzahl beurteilt.'],'portfolio'),
 q('17','a','A cost approach to property valuation is most limited by the fact that:',[['Construction expenditure need not be supported by sufficient user demand or income.','Kosten schaffen keinen Anspruch auf entsprechende künftige Zahlungen.'],['Land can never be relevant to replacement economics.','Boden und Nutzung sind wesentliche Teile der Analyse.'],['It directly measures an executable listed share quotation.','Das ist eine andere Preisgröße.']],['Wiederbeschaffung, Abnutzung und wirtschaftliche Nachfrage müssen zusammen geprüft werden.'],'valuation-methods'),
 q('18','a','Sales comparison is most informative when the analyst:',[['Adjusts recent comparable transactions for property and contract differences.','Ein Vergleich braucht ähnliche wirtschaftliche Bedingungen.'],['Uses any older national sale without adjustment.','Zeit, Standort und Nutzung können wesentlich abweichen.'],['Assumes the highest construction cost sets a guaranteed resale price.','Kosten und tatsächlich erzielbarer Marktpreis sind verschieden.']],['Vergleichbarkeit ist eine begründete Analyse und kein bloßes Übernehmen einer Zahl.'],'valuation-methods'),
 q('19','a','A private real estate fund adds management and pooling to direct property exposure. The analyst should additionally examine:',[['Fees, governance, valuation policies and investor liquidity restrictions.','Die Vehikelebene kann zusätzliche Kosten und Rechte schaffen.'],['Only whether the fund title contains the word core.','Das Etikett beantwortet Vertragsfragen nicht.'],['An assumed right to withdraw immediately at the last NAV.','Ein solches Rückgaberecht muss ausdrücklich bestehen.']],['Assetrisiko und Fondsbedingungen sind zwei Analyseebenen.'],'access'),
 q('20','a','An investor holds an airport and adjacent shopping property. Falling air traffic affects both. This principally demonstrates:',[['Different legal assets can share a common economic driver.','Besucherfrequenz wirkt auf Nutzerentgelte und Ladenmieten.'],['Real estate and infrastructure necessarily have negative correlation.','Der Fall zeigt gerade einen möglichen gemeinsamen Stress.'],['Separate legal ownership removes all shared demand exposure.','Rechtsform verändert den gemeinsamen Bedarf nicht automatisch.']],['Eine Portfoliostruktur braucht eine Analyse der Zahlungsquellen.'],'portfolio'),
 n('21','b','NOI is 600. Additional capex is 80, interest 200 and principal repayment 100. With no other flows, equity cash is:',[['220.00.','600 minus alle drei tatsächlich bezeichneten Mittelbindungen.'],['520.00.','Das ist Cash vor Finanzierung.'],['300.00.','Das ignoriert zusätzliches Capex.']],'Z=600-80-200-100=220','Finanzierung und Investitionen sind im NOI noch nicht abgezogen.','cashflow','Verbleibende Eigenkapitalzahlung, WE.'),
 n('22','b','A reserve opens at 50, receives 10 from operating cash and pays 40 directly for renewal. Its closing balance is:',[['20.00.','50 plus zehn Einzahlung minus 40 Auszahlung.'],['60.00.','Das ignoriert die tatsächlich bezahlte Erneuerung.'],['-20.00.','Das zieht dieselbe Auszahlung zweimal ab.']],'Z=50+10-40=20','Ausgaben aus einer Reserve sind mit deren Bestandsänderung abzustimmen.','reserves','Gebundener Reservebestand am Jahresende, WE.'),
 n('23','b','A sustainable annual NOI of 100 is capitalized first at 5% and then at 6%, on the same income basis. The percentage value decline is closest to:',[['16.666667%.','2000 fällt auf 1666,666667; Verlust relativ zu 2000.'],['1.000000%.','Das verwechselt Prozentpunkte des Satzes mit Wertänderung.'],['20.000000%.','Das setzt den Verlust zum neuen statt alten Preis ins Verhältnis.']],'Z=100[1-(100/0{,}06)/(100/0{,}05)]\\approx16{,}666667','Die Kehrwertbeziehung erzeugt eine größere und gekrümmte Preiswirkung.','cap-rate','Relativer Wertverlust gegenüber dem Ausgangswert, Prozent.'),
 n('24','b','Current annual NOI is 100, next-year NOI 102 and today’s price 2000. The forward NOI cap rate is:',[['5.10%.','102 nächstjähriger NOI geteilt durch heutigen Preis.'],['5.00%.','Das ist die Current-NOI-Quote.'],['2.00%.','Das ist NOI-Wachstum statt Cap Rate.']],'Z=100(102/2000)=5{,}1','Beide Quoten sind möglich, müssen aber nach ihrer Periode bezeichnet werden.','periods','Forward-NOI-Cap-Rate, Prozent.'),
 n('25','b','Next-year NOI is 100, 10% of NOI is recurring capex, price is 2000 and remaining cash grows perpetually at 2%. Under a consistent constant-growth valuation, the required annual return is:',[['6.50%.','4,5 Prozent verfügbare Cashrendite plus zwei Prozent Wachstum.'],['7.00%.','Das addiert Brutto-NOI-Cap und Wachstum ohne Capex.'],['4.50%.','Das lässt das ausdrücklich ewige Wachstum aus.']],'Z=100[0{,}9(100)/2000+0{,}02]=6{,}5','Die Gordon-Beziehung verwendet verfügbaren nächsten Cashflow, nicht unbereinigten NOI.','growth-return','Konsistente jährliche Rendite unter den bezeichneten ewigen Annahmen, Prozent.'),
 q('26','b','An analyst changes only the discount rate used to value fixed forecast property cash flows, keeping price and all actual cash flows unchanged. The investment’s cash-flow IRR:',[['Remains unchanged.','Die Zahlungsreihe und ihr Kaufpreis ändern sich nicht.'],['Must become equal to the new discount rate.','Die Renditeforderung definiert nicht automatisch den internen Zins.'],['Increases whenever the discount rate decreases.','Das beschreibt eine DCF-Wirkung, keine Änderung derselben Zahlungs-IRR.']],['Ein Bewertungsanspruch und der aus Zahlungen ermittelte interne Zins sind verschiedene Größen.'],'causality'),
 q('27','b','An investor lowers only the purchase price for unchanged property cash flows and discount assumptions. The most likely effects are:',[['Unchanged DCF of receipts, higher NPV and higher investment IRR.','Der Wert der Rückflüsse bleibt gleich, der Anfangseinsatz sinkt.'],['Higher DCF of receipts solely because the purchase price fell.','Der bezahlte Preis ist keine zusätzliche positive Rückflusszahlung.'],['Unchanged IRR because rents did not change.','Ein geringerer Einsatz verändert die Rendite der gleichen Rückflüsse.']],['NPV vergleicht prognostizierten Wert mit gezahltem Preis.'],'causality'),
 n('28','b','NOI in year one is 100, grows 2% annually and is sold at the end of year five at a 5% cap rate on year-six NOI. Gross sale value is closest to:',[['2208.161606.','100 mal 1,02 hoch fünf geteilt durch 0,05.'],['2164.864320.','Das kapitalisiert Jahr fünf statt Jahr sechs.'],['2000.000000.','Das ignoriert das angesetzte Wachstum.']],'Z=100(1{,}02)^5/0{,}05\\approx2208{,}161606','Ein Forward-Exit verwendet den NOI des ersten Käuferjahres.','exit','Bruttoverkaufswert am Ende des fünften Jahres, WE.'),
 n('29','b','Using the previous gross sale value of 2208.1616064, sale costs equal 2% of gross sale. Net sale proceeds are:',[['2163.998374.','Bruttoerlös mal 0,98.'],['2164.864320.','Das ist ein anderer NOI-Zeitpunkt und kein Kostenabzug.'],['2252.324839.','Das addiert statt subtrahiert die Kosten.']],'Z=2208{,}1616064(1-0{,}02)\\approx2163{,}998374','Kosten werden einmal auf die ausdrücklich bezeichnete Bruttobasis angewandt.','exit','Nettoverkauf nach Kosten, WE.'),
 n('30','b','A property has initial price 2000, first-year NOI 100 growing 2%, annual capex 10% of NOI, five holding years, 5% forward exit cap and no sale costs. At 8%, its DCF is closest to:',[['1875.709421.','Barwerte der fünf Nettojahreszahlungen plus diskontierter Verkauf.'],['1917.139614.','Das lässt das bezeichnete Capex unberücksichtigt.'],['2208.161606.','Das ist nur der nicht diskontierte Bruttoverkauf.']],'Z=\\sum_{t=1}^{5}90(1{,}02)^{t-1}/(1{,}08)^t+[100(1{,}02)^5/0{,}05]/(1{,}08)^5\\approx1875{,}709421','Laufender Cashflow und Exit werden mit ihren tatsächlichen Terminen jeweils einmal berücksichtigt.','dcf-case','Heutiger Wert des bezeichneten ungehebelten Zahlungsplans, WE.'),
 n('31','b','The DCF of expected receipts is 1875.709421 and the purchase price is 2000. NPV is:',[['-124.290579.','Bewertete Rückflüsse minus Anfangspreis.'],['124.290579.','Das kehrt den Vergleich um.'],['1875.709421.','Das ist Wert vor Kaufpreisabzug.']],'Z=1875{,}709421-2000=-124{,}290579','Ein positiver DCF kann trotzdem einen negativen Kapitalwert relativ zum geforderten Preis ergeben.','dcf-case','Kapitalwert beim bezeichneten Preis, WE.'),
 n('32','b','The present value of sale proceeds is 1502.83768565 and total property DCF is 1875.70942141. The terminal-sale share of value is closest to:',[['80.121029%.','Verkaufsbarwert relativ zum gesamten DCF.'],['117.724490%.','Das verwendet den nicht diskontierten Verkauf als Zähler.'],['19.878971%.','Das ist der komplementäre Anteil laufender Zahlungen.']],'Z=100(1502{,}83768565/1875{,}70942141)\\approx80{,}121029','Ein hoher Schlusswertanteil macht die Exitannahme besonders bedeutsam, ist aber keine Eintrittswahrscheinlichkeit.','terminal-risk','Barwertanteil des Schlussverkaufs, Prozent.'),
 n('33','b','A property costs 2000, provides annual cash after capex of 90 and sells for 2000 one year later. Debt is 1200 at 5%, with principal repaid at sale. Equity return is:',[['3.75%.','30 laufendes EK-Cash plus 800 Exit relativ zu 800 Anfangseinsatz.'],['4.50%.','Das ist die ungehebelte Objektrendite.'],['11.25%.','Das teilt Objektcash durch Eigenkapital ohne Kreditzins.']],'Z=100[(90-0{,}05(1200)+2000-1200)/800-1]=3{,}75','Kredit kostet hier mehr als die laufende ungehebelte Cashrendite.','leverage','Einjährige Gesamtrendite des Eigenkapitals, Prozent.'),
 Q("rea-34",
   "real-assets",
   "alternatives",
   "practice",
   "b",
   "A property costs 2000 and produces annual cash after capex but before debt service of 90. Debt of 1200 costs 5% for the year, with principal repaid at sale. The property sells for 2100 one year later. With no other flows or costs, the one-year equity return is:",
   [["16.25%.","30 laufendes Cash plus 900 Exit gegen 800 Anfangseinsatz."],["9.50%.","Das ist die Objektrendite ohne Schuld."],["12.50%.","Das berücksichtigt nur den Preisgewinn auf Eigenkapital."]],
   0,
   [{"kind":"formula","tex":"\\begin{aligned}E_0&=2000-1200=800\\\\ I&=1200(0{,}05)=60\\\\ CF_E&=90-60=30\\end{aligned}","reading":"Die anfängliche Eigenkapitalzahlung ist Objektpreis abzüglich Fremdfinanzierung. Aus dem laufenden Cash nach Capex werden danach die Kreditzinsen bezahlt. Die Kapitaltilgung folgt erst beim Verkauf.","symbols":[["E_0","Anfänglicher Eigenkapitaleinsatz, WE."],["I","Jährliche Zinszahlung auf die unveränderte Schuld, WE."],["CF_E","Laufender Jahrescashflow für die Eigentümer nach Capex und Zins, vor der gesonderten Endtilgung, WE."]]},{"kind":"formula","tex":"E_T=2100-1200=900,\\qquad R_E=\\frac{30+900-800}{800}=0{,}1625","reading":"Der Exit liefert nach Schuldentilgung 900. Zusammen mit dem laufenden Cash 30 entsteht gegenüber dem Eigenkapitaleinsatz 800 ein Gewinn 130 und damit 16,25 Prozent Gesamtrendite.","symbols":[["E_T","Eigenkapitalerlös aus dem Verkauf nach vollständiger Endtilgung, WE."],["R_E","Einjährige Eigenkapitalgesamtrendite als Dezimalrendite; 0,1625 entspricht 16,25 Prozent."]]},"Ohne Fremdfinanzierung wären 90 laufendes Cash plus 100 Preisgewinn auf 2000 Objektpreis nur 9,5 Prozent. Die 12,5-Prozent-Alternative erfasst dagegen nur den Preisgewinn 100 auf Eigenkapital 800 und lässt das laufende Netto-Cash 30 weg. Fremdfinanzierung verstärkt günstige wie ungünstige Preisbewegungen; der Fall zeigt keine garantierte Mehrverzinsung."],
   {"section":"leverage"}),
 n('35','b','Property values are 1000, other assets 50, financial debt 400, other liabilities 50 and shares 100. NAV per share is:',[['6.00.','600 Nettovermögenswert geteilt durch 100 Aktien.'],['10.00.','Das teilt nur den Bruttoobjektwert auf Aktien.'],['6.50.','Das ignoriert die übrigen Verpflichtungen.']],'Z=(1000+50-400-50)/100=6','Alle bezeichneten Ansprüche werden auf derselben Bewertungsebene übergeleitet.','nav','Geschätzter NAV je gewöhnlicher Aktie, WE je Aktie.'),
 n('36','b','In an explicitly simplified REIT case, net income is 20, qualifying real estate depreciation 15 and relevant real estate sale gain 5. No other FFO adjustments apply. FFO is:',[['30.00.','20 plus 15 Abschreibung minus fünf Veräußerungsgewinn.'],['40.00.','Das addiert den Verkaufsgewinn erneut statt ihn zu entfernen.'],['20.00.','Das ist unverändertes Ergebnis ohne Überleitung.']],'Z=20+15-5=30','Die genaue Kennzahlendefinition bleibt maßgeblich; FFO ist keine Dividendenzusage.','ffo','FFO unter den ausdrücklich vollständigen Fallangaben, WE.'),
 n('37','b','The same case has FFO 30. Its disclosed, case-specific AFFO rule deducts recurring capex 8 and unreceived straight-line rent 2. Case AFFO is:',[['20.00.','Beide zusätzlichen Korrekturen werden einmal abgezogen.'],['22.00.','Das ignoriert noch nicht erhaltene Miete.'],['30.00.','Das ist FFO vor den ausdrücklich genannten weiteren Anpassungen.']],'Z=30-8-2=20','Diese offengelegte Fallregel ist keine universelle AFFO-Definition.','ffo','AFFO nach der bezeichneten eigenen Anpassungsregel, WE.'),
 n('38','b','Initial rent 200 and operating costs 100 produce NOI 100. Rent rises only 2%, while costs and the general price level rise 10%. New real NOI in old-price units is:',[['85.454545.','Nominal 94 wird durch 1,10 deflationiert.'],['94.000000.','Das ist neuer nominaler NOI.'],['102.000000.','Das überträgt allein Mietwachstum auf den früheren NOI.']],'Z=[200(1{,}02)-100(1{,}10)]/1{,}10\\approx85{,}454545','Mietanstieg kann von Kostenanstieg übertroffen werden; realer und nominaler Schutz unterscheiden sich.','inflation','Neuer Jahres-NOI in Einheiten des alten Preisniveaus, WE.'),
 q('39','b','A finite property model has explicitly specified cash flows, a positive exogenous exit price and growth exceeding its discount rate. The best assessment is:',[['A finite DCF can be computed, but the assumptions still require economic justification.','Ein endlicher Plan braucht keine konvergente unendliche Gordon-Reihe.'],['Every finite DCF is mathematically undefined whenever growth exceeds discount.','Diese Konvergenzbedingung betrifft die unendliche konstante Wachstumsrente.'],['The same inputs automatically justify a perpetual Gordon value.','Die unendliche Formel verlangt eine passende positive Differenz zwischen Diskontsatz und Wachstum.']],['Rechenbarkeit eines endlichen Szenarios ist kein Beweis plausibler ewiger Annahmen.'],'dcf'),
 q('40','b','A REIT trades below estimated NAV. The most defensible interpretation is:',[['The discount may reflect costs, risks or appraisal uncertainty and is not itself guaranteed arbitrage.','Geschätzter NAV und ausführbarer Verkauf sind verschiedene Größen.'],['Investors can necessarily liquidate every asset immediately at its last valuation.','Ein solches Recht und ein solcher Marktpreis sind nicht gegeben.'],['The share must generate exactly the discount as next-year return.','Bewertungslücke und künftige Rendite sind nicht identisch.']],['Management, Finanzierung, Informationszeitpunkt und tatsächliche Liquidierbarkeit sind mitzuprüfen.'],'nav'),
 q('41','c','Infrastructure investments are most commonly associated with:',[['Long-lived, capital-intensive assets providing essential economic or social services.','Leistung, Lebensdauer und Kapitalbedarf erklären typische Merkmale.'],['Short-lived standardized inventory only.','Das entspricht nicht dem typischen Infrastrukturprofil.'],['A single universal contract paying all investors the same amount.','Zahlungsrechte und Risiken unterscheiden sich nach Projekt und Anspruch.']],['Die Kategorie umfasst unterschiedliche technische und vertragliche Modelle.'],'infrastructure'),
 q('42','c','Which is most clearly an example of social infrastructure?', [['A school building provided under a long-term service contract.','Eine öffentliche Bildungsfunktion passt zur sozialen Infrastruktur.'],['A toll road linking freight centers.','Das ist typischerweise wirtschaftliche Verkehrsinfrastruktur.'],['An ordinary diversified portfolio of short-term commercial paper.','Das ist kein entsprechendes physisches Infrastrukturprojekt.']],['Die Einordnung beschreibt Nutzung; sie garantiert nicht das Zahlungsprofil.'],'infrastructure'),
 q('43','c','A newly planned water treatment plant requiring permits, construction and commissioning is:',[['A greenfield project with development and completion exposure.','Die Betriebsanlage muss erst entstehen.'],['A brownfield operating asset solely because it will be long-lived.','Lange spätere Lebensdauer macht keinen bestehenden Betrieb.'],['A completed project free of technical risk.','Der Bau ist im Fall noch nicht erfolgt.']],['Projektphase erklärt, welche Zahlungen und Ausführungsrisiken zuerst auftreten.'],'stages'),
 q('44','c','An operating transmission network with a history of costs and service performance is more consistent with:',[['Brownfield infrastructure, which still has operating and renewal risks.','Ein bestehender Betrieb liefert mehr Beobachtung, beseitigt aber Folgepflichten nicht.'],['Greenfield infrastructure solely because future capex may occur.','Spätere Erhaltung allein macht den bestehenden Betrieb nicht zu einem neuen Entwicklungsprojekt.'],['A riskless state security.','Ein Netzbetrieb ist kein solcher garantierter Anspruch.']],['Betriebsdaten helfen, sind jedoch keine Garantie künftiger Regulierung oder Kosten.'],'stages'),
 q('45','c','A toll project’s receipts equal the charge per vehicle multiplied by paying traffic. Its primary revenue model is:',[['User-pay with direct demand exposure.','Die bezahlte Nutzungsmenge bestimmt Einnahmen.'],['Fixed availability payment independent of traffic.','Das wäre ein anderer Vertrag.'],['A guaranteed equity coupon independent of all service outcomes.','Eine solche Garantie ist nicht bezeichnet.']],['Tarif, Mengen, Preiselastizität und Ausweichmöglichkeiten sind zu untersuchen.'],'user-pay'),
 q('46','c','A public authority pays for a facility being available to a specified standard, subject to performance deductions. The operator still faces:',[['Performance, contractual and counterparty payment risks.','Verfügbarkeit muss erreicht und die vereinbarte Zahlung geleistet werden.'],['No risk because user traffic is not the direct payment base.','Die Verlagerung eines Mengenrisikos beseitigt andere Risiken nicht.'],['Only changes in the number of paying drivers.','Das ist gerade nicht die angegebene Zahlungsbasis.']],['Verfügbarkeitszahlung und Nutzerentgelt verteilen Risiken unterschiedlich.'],'availability'),
 q('47','c','An allowed regulatory return of 8% is quoted on an approved capital base. An analyst should first:',[['Identify that capital base and all other permitted and actual cash flows.','Erlaubte Rendite, anerkannte Basis und tatsächlicher Einsatz können verschieden sein.'],['Treat 8% as the guaranteed annual equity IRR.','Das folgt nicht aus einer einzelnen Vergütungskomponente.'],['Ignore differences between approved and actual construction costs.','Gerade diese Unterschiede können den Anlegerertrag beeinflussen.']],['Eine regulatorische Quote ist keine vollständige Anlegerzahlungsreihe.'],'regulated'),
 q('48','c','A build–operate–transfer contract ends with uncompensated handover of all private rights. At that date, the investor should:',[['Use the actual contractual residual claim, which may be zero before handback costs.','Physischer Fortbestand erzeugt keinen weiteren privaten Eigentumsanspruch.'],['Assume an unrestricted perpetual resale value.','Das widerspricht dem Ende sämtlicher privater Rechte.'],['Add the entire public asset value to final cash automatically.','Ein öffentlicher Nutzen ist kein zusätzlich gezahlter Privatverkauf.']],['Vertragsende, Entschädigung und Rückgabepflichten bestimmen den Schlussrückfluss.'],'concession'),
 q('49','c','A ring-fenced project company finances an infrastructure asset. Which conclusion is most defensible?', [['Credit support and recourse must be read from the actual contracts.','Eine separate Gesellschaft begründet nicht jede denkbare Garantie.'],['Every project debt is automatically a direct government obligation.','Projektgesellschaft und öffentlicher Haushalt sind nicht identisch.'],['The sponsor can never have any support obligation.','Zusagen und Rückgriffe können vertraglich bestehen.']],['Gesellschaft, Kreditnehmer und Garant sind getrennte Rollen.'],'project-structure'),
 q('50','c','Public–private partnership describes:',[['A contractual arrangement whose allocation of construction, service and financial risks must be assessed.','Die konkrete Risikozuordnung folgt dem Vertrag.'],['A universal guarantee of equity profits by taxpayers.','Eine solche Garantie folgt nicht aus der Bezeichnung.'],['A requirement that all funding be equity.','PPP legt nicht pauschal diese Kapitalstruktur fest.']],['Öffentliche Beteiligung und Anlegerabsicherung sind unterschiedliche Aussagen.'],'project-structure'),
 q('51','c','A long-term energy offtake agreement can reduce some market-volume or price uncertainty but adds the need to examine:',[['The buyer’s creditworthiness and enforceability of the agreement.','Eine versprochene Abnahme muss bezahlt und rechtlich durchsetzbar sein.'],['Only the physical age of the turbines.','Technik allein prüft den Zahlungsverpflichteten nicht.'],['An assumption that counterparty default is impossible.','Die Vertragsdauer beweist keine Zahlungsfähigkeit.']],['Risikoverlagerung ist keine Risikobeseitigung.'],'currency-policy'),
 q('52','c','A tariff indexed with a one-year delay and a cap is best described as:',[['Potential partial inflation protection with basis and timing limitations.','Kosten können anders oder früher steigen als der Tarif.'],['Perfect contemporaneous protection against every project cost increase.','Das ignoriert den ausdrücklich begrenzten Anpassungsmechanismus.'],['A contract with no nominal revenue adjustment.','Eine begrenzte Indexierung ist dennoch eine Anpassung.']],['Index, Verzögerung, Obergrenze und Kostenstruktur sind gemeinsam zu prüfen.'],'currency-policy'),
 q('53','c','A tunnel cannot be easily converted to another use. This most directly illustrates:',[['Asset specificity and potentially limited alternative recovery value.','Die technische Spezialisierung kann andere Verwertungen begrenzen.'],['Guaranteed full recovery for every lender.','Eine spezialisierte Anlage garantiert keinen zahlungsfähigen Käufer.'],['The absence of maintenance obligations.','Spezifische Nutzung kann gerade hohe Erhaltung verlangen.']],['Physische Lebensdauer und wirtschaftlicher Verwertungswert sind verschieden.'],'infrastructure'),
 q('54','c','A brownfield project requires a major equipment replacement five years from now. The valuation should:',[['Include the expected renewal cash outflow at its proper date.','Bestehender Betrieb benötigt gegebenenfalls weitere echte Mittel.'],['Exclude it because all brownfield projects are already complete.','Betriebsbeginn beendet nicht die Lebenszykluskosten.'],['Deduct the same full cash payment in every year regardless of timing.','Das würde Betrag und Termin verändern.']],['Capex und gegebenenfalls Reserven werden ohne Doppelzählung geplant.'],'handback'),
 q('55','c','A project has local-currency receipts but foreign-currency debt service. Local currency depreciation most directly creates:',[['A possible increase in the local-currency cash required for debt service.','Mehr lokale Einheiten können je fremder Einheit nötig werden.'],['An automatic increase in local revenues by the same amount.','Eine passende Umsatzanpassung ist nicht gegeben.'],['No issue as long as the physical asset remains unchanged.','Finanzierungszahlungen können sich ohne physischen Wandel verteuern.']],['Währungszuordnung ist Teil der Projekttragfähigkeit.'],'currency-policy'),
 q('56','c','A portfolio combines two infrastructure funds invested in the same regional transport demand. The diversification assessment should:',[['Look through the fund labels to shared traffic, funding and regional exposures.','Rechts- und Fondsnamen können denselben wirtschaftlichen Treiber überdecken.'],['Assume independent returns because the managers differ.','Getrennte Manager beseitigen den gemeinsamen Bedarf nicht.'],['Use asset count as a sufficient covariance estimate.','Die Anzahl liefert noch keinen statistischen Zusammenhang.']],['Ökonomische Treiber sind für das gemeinsame Stressverhalten relevant.'],'portfolio'),
 q('57','c','An infrastructure asset’s long physical life is most consistent with which liquidity conclusion?', [['Long life can coexist with large short-term cash calls and an illiquid sale process.','Bau, Erhaltung und Finanzierung können vorher Geld benötigen.'],['All near-term liabilities must therefore be covered.','Die spätere Nutzbarkeit ist kein heutiger Kassenbestand.'],['The investor can always sell at par within one day.','Daraus folgt kein Börsen- oder Rückgaberecht.']],['Fristigkeit der Anlage und Zahlungsfähigkeit werden getrennt geplant.'],'portfolio'),
 q('58','c','Which distinction matters most when valuing a concession compared with perpetual ownership?', [['The duration and residual rights of the investor’s actual claim.','Die berechtigten Zahlungen können mit dem Vertrag vollständig enden.'],['Whether concrete remains physically present.','Physischer Bestand allein begründet keinen privaten Rückfluss.'],['Whether the asset is socially useful.','Nutzen und privater Anspruch sind unterschiedliche Größen.']],['Eine endliche Nutzungsberechtigung wird nicht ohne Begründung zur ewigen Rente.'],'concession'),
 q('59','c','A regulated water network faces a change in allowed cost recovery. This is most directly:',[['A regulatory risk affecting the relationship between costs and permitted receipts.','Anerkennung und Vergütung können sich ändern.'],['Only a listed-equity trading cost.','Der Eingriff wirkt bereits auf Projekteinnahmen und Finanzierung.'],['Proof that service demand has disappeared.','Vergütungsregeln können sich auch bei unveränderter Nachfrage ändern.']],['Politik, Recht, Preisregeln und technische Leistung wirken auf verschiedenen Wegen.'],'regulated'),
 q('60','c','Relative to an operating project, a greenfield project most clearly requires additional analysis of:',[['Permitting, completion timing, cost overruns and commissioning before stable operation.','Die Ertragsquelle muss zunächst erfolgreich errichtet werden.'],['Only historical operating distributions from the identical finished asset.','Solche eigenen Betriebserfahrungen fehlen vor Fertigstellung.'],['An assumption of immediate full operating cash on the construction date.','Das überspringt Bau und Inbetriebnahme.']],['Frühe Kosten und spätere Einnahmen erklären einen wesentlichen Teil des Projektrisikos.'],'stages'),
 n('61','d','A user-pay project charges 2 per unit, variable cost is 0.5 per unit, fixed operating costs are 80 and paid volume is 100. Cash before financing and other investment is:',[['70.00.','200 Erlös minus 50 variable und 80 fixe Kosten.'],['120.00.','Das ignoriert variable Kosten.'],['150.00.','Das ist Deckungsbeitrag vor fixen Kosten.']],'Z=(2-0{,}5)(100)-80=70','Die bezahlte Menge wirkt über den Deckungsbeitrag, fixe Kosten bleiben im Fall bestehen.','user-pay','Operativer Jahrescashflow vor weiteren bezeichneten Positionen, WE.'),
 Q("rea-62",
   "real-assets",
   "alternatives",
   "practice",
   "d",
   "A user-pay project charges 2 per paid unit, incurs variable cash cost of 0.5 per unit and fixed operating cash costs of 80. Paid volume is 60. With no other flows, cash before financing and other investment is:",
   [["10.00.","90 Deckungsbeitrag minus 80 fixe Kosten."],["42.00.","Das vermindert den früheren Cashflow proportional und ignoriert fixe Kosten."],["40.00.","Das zieht nur Fixkosten von Umsatz ab und lässt variable Kosten weg."]],
   0,
   [{"kind":"formula","tex":"Z=(2-0{,}5)(60)-80=10","reading":"Ein vierzigprozentiger Mengenrückgang kann den Überschuss viel stärker vermindern.","symbols":[["Z","Operativer Cashflow beim geringeren Volumen, WE."]]}],
   {"section":"user-pay"}),
 n('63','d','With a charge of 2, variable unit cost 0.5 and annual fixed operating costs 80, break-even paid volume before financing is closest to:',[['53.333333.','Fixkosten geteilt durch 1,5 Deckungsbeitrag je Einheit.'],['40.000000.','Das ignoriert variable Stückkosten.'],['160.000000.','Das teilt durch Stückkosten statt Deckungsbeitrag.']],'Z=80/(2-0{,}5)\\approx53{,}333333','Bei diesem kontinuierlich betrachteten Volumen deckt der Beitrag gerade die bezeichneten Fixkosten.','user-pay','Operative Break-even-Menge in Einheiten pro Jahr.'),
 n('64','d','An availability contract pays 200 annually before performance deductions. Deductions are 40 and operating cash costs 100. Cash before other investment and financing is:',[['60.00.','200 minus 40 Leistungsabzug minus 100 Betrieb.'],['100.00.','Das ignoriert den vereinbarten Leistungsabzug.'],['160.00.','Das ist Zahlung nach Abzug, aber vor Betriebskosten.']],'Z=200-40-100=60','Fehlende direkte Verkehrsabhängigkeit beseitigt Leistungsbedingungen nicht.','availability','Jahrescash vor weiterem Capex und Finanzierung, WE.'),
 n('65','d','A hypothetical regulator allows an annual capital-return component of 8% on approved base 100. Actual invested capital is 120. That component relative to actual investment is:',[['6.666667%.','Acht erlaubte WE relativ zu 120 tatsächlichem Einsatz.'],['8.000000%.','Das verwendet die anerkannte statt tatsächlichen Basis.'],['9.600000%.','Das multipliziert die Quote mit dem umgekehrten Basisfaktor.']],'Z=100[0{,}08(100)/120]\\approx6{,}666667','Die isolierte Komponente ist noch keine vollständige Projekt- oder Eigenkapital-IRR.','regulated','Erlaubter Kapitalertragsbaustein relativ zum tatsächlichen Einsatz, Prozent.'),
 n('66','d','A concession pays 20 at the end of each of ten years and then all private rights terminate without compensation. At 8%, its value before acquisition cost is closest to:',[['134.201628.','Endliche zehnjährige Jahresendrente ohne Restverkauf.'],['250.000000.','Das wäre eine unendliche Zahlung.'],['200.000000.','Das ignoriert Diskontierung.']],'Z=20[1-(1{,}08)^{-10}]/0{,}08\\approx134{,}201628','Die endliche Anspruchsdauer und der erste Zahlungstermin sind ausdrücklich gegeben.','concession','Heutiger Wert der zehn privaten Vertragszahlungen, WE.'),
 Q("rea-67",
   "real-assets",
   "alternatives",
   "practice",
   "d",
   "A ten-year concession costs 100 today and receives 20 at the end of each of the ten years. There is no residual value or other cash flow, and the appropriate annual discount rate is 8%. NPV is closest to:",
   [["34.201628.","Barwert 134,201628 abzüglich Bau-/Kaufkosten 100."],["134.201628.","Das ist Rückflusswert vor dem Anfangseinsatz."],["100.000000.","Das verwechselt undiskontierten Überschuss mit Kapitalwert."]],
   0,
   [{"kind":"formula","tex":"Z=-100+20[1-(1{,}08)^{-10}]/0{,}08\\approx34{,}201628","reading":"Anfangsauszahlung und spätere Rückflüsse stehen zu verschiedenen Zeitpunkten.","symbols":[["Z","Kapitalwert des eigenen Projektplans, WE."]]}],
   {"section":"stages"}),
 n('68','d','The ten payments of 20 are delayed by one year, to years 2 through 11. Initial cost stays 100 today, discount is 8% and there are no other changes. NPV is closest to:',[['24.260767.','Die gesamte zehnjährige Zahlungsrente wird ein weiteres Jahr abgezinst.'],['34.201628.','Das ignoriert den Verzug.'],['15.683109.','Das lässt zusätzlich die letzte erlaubte Zahlung entfallen, obwohl Jahr elf vereinbart ist.']],'Z=-100+\\{20[1-(1{,}08)^{-10}]/0{,}08\\}/1{,}08\\approx24{,}260767','Alle zehn Zahlungen bleiben erhalten, werden aber später empfangen.','delay','Kapitalwert bei verschobenem Beginn und entsprechend verschobenem Ende, WE.'),
 n('69','d','Instead, the concession still expires in year 10 after a one-year delay. Only nine payments of 20, in years 2 through 10, remain. With initial cost 100 and 8% discount, NPV is closest to:',[['15.683109.','Die erste Betriebszahlung fällt aus; Ende bleibt Jahr zehn.'],['24.260767.','Das würde ein zusätzliches elftes Jahr zulassen.'],['34.201628.','Das ignoriert die verlorene frühe Zahlung.']],'Z=-100+20[1-(1{,}08)^{-10}]/0{,}08-20/1{,}08\\approx15{,}683109','Verlorene Zahlungsjahre und bloß verschobene Zahlungstermine sind verschieden.','delay','Kapitalwert bei verzögertem Beginn und festem Ende, WE.'),
 n('70','d','An additional construction overrun of 5 is paid today in a project whose previously calculated NPV was 24.260767. No other cash flow changes. New NPV is:',[['19.260767.','Heutige Mehrkosten reduzieren heutigen Kapitalwert eins zu eins.'],['29.260767.','Das addiert Kosten als Ertrag.'],['24.260767.','Das ignoriert die zusätzliche Zahlung.']],'Z=24{,}260767-5=19{,}260767','Ein späterer Mehrkostenbetrag müsste dagegen zu seinem tatsächlichen Termin abgezinst werden.','delay','Neuer Kapitalwert nach sofortiger zusätzlicher Bauzahlung, WE.'),
 n('71','d','Project cash before a mandatory reserve is 24. The reserve contribution of 6 is unavailable for debt service. Interest is 4 and principal due is 12. DSCR under this contract is:',[['1.125.','18 tatsächlich verfügbare WE relativ zu 16 Schuldendienst.'],['1.500.','Das verwendet gebundene Reservemittel als frei verfügbar.'],['4.500.','Das lässt die fällige Tilgung im Nenner weg.']],'Z=(24-6)/(4+12)=1{,}125','Die Vertragsdefinition legt fest, welche Mittel Schuldendienst decken dürfen.','infrastructure-debt','Schuldendienstdeckungsfaktor nach der bezeichneten Kreditregel.'),
 Q("rea-72",
   "real-assets",
   "alternatives",
   "practice",
   "d",
   "Project cash before a mandatory reserve contribution is 24. The reserve contribution of 6 is unavailable for debt service or distribution. Interest of 4 and principal of 12 are due. With no other flows, unrestricted cash remaining after the reserve contribution and due debt service is:",
   [["2.00.","18 verfügbar minus 16 fälliger Schuldendienst."],["8.00.","Das ignoriert die sechs gebundene Reserve."],["18.00.","Das ist verfügbares Cash vor Schuldendienst."]],
   0,
   [{"kind":"formula","tex":"Z=24-6-4-12=2","reading":"Aktuelle Deckung lässt nur einen kleinen Puffer und garantiert keine künftige Deckung.","symbols":[["Z","Verbleibender Jahreskassenpuffer, WE."]]}],
   {"section":"infrastructure-debt"}),
 n('73','d','Ten annual end-year receipts of 20 are valued at 8%. A separate handback obligation of 30 is paid at the end of year 10. Net value is closest to:',[['120.305823.','Barwert der Rente minus Barwert des späteren Aufwands.'],['104.201628.','Das zieht den gesamten späteren Betrag schon heute undiskontiert ab.'],['134.201628.','Das ignoriert Rückgabekosten.']],'Z=20[1-(1{,}08)^{-10}]/0{,}08-30/(1{,}08)^{10}\\approx120{,}305823','Der Endaufwand hat seinen eigenen Termin und wird einmal abgezogen.','handback','Heutiger Vertragswert nach zusätzlichem Rückgabeaufwand, WE.'),
 n('74','d','A project receives local-currency cash 100 and owes debt service of 10 foreign units. Exchange rate is now 12 local units per foreign unit. Local cash surplus after debt service is:',[['-20.00.','100 Einnahmen minus 120 lokaler Schuldendienst.'],['20.00.','Das verwendet den früheren Kurs acht statt zwölf.'],['90.00.','Das zieht unterschiedliche Währungseinheiten direkt voneinander ab.']],'Z=100-10(12)=-20','Der negative Puffer bezeichnet einen zusätzlichen Finanzierungsbedarf, keinen automatisch verfügbaren Kredit.','currency-policy','Lokaler Cashpuffer nach Fremdwährungsschuldendienst, WE.'),
 q('75','d','An infrastructure loan reports DSCR above one for the current year. The strongest justified conclusion is:',[['The defined available cash covers the defined current debt service under that calculation.','Die Aussage betrifft diese Cashbasis und Periode.'],['All future debt and refinancing are guaranteed.','Eine heutige Quote ist keine lebenslange Garantie.'],['The equity investment necessarily earns its required return.','Schuldendienstdeckung und Eigenkapitalrendite beantworten andere Fragen.']],['Testzeitpunkt, Reserven, Covenants und spätere Investitionen bleiben relevant.'],'infrastructure-debt'),
 q('76','d','An investor plans to match a long-dated liability with infrastructure distributions. The analysis should include:',[['Cash-flow timing, currency, reliability, liquidity and possible capital calls.','Eine lange Anlage allein deckt die konkrete Verpflichtung nicht.'],['Only the engineering life of the asset.','Das legt weder Anspruchsdauer noch erhaltene Zahlungen fest.'],['A guaranteed ability to liquidate at the last appraisal whenever needed.','Das ist ohne entsprechendes Recht und Marktbedingungen nicht gegeben.']],['Liability Matching benötigt passende tatsächliche Mittelzuflüsse und Reserven.'],'portfolio'),
 q('77','d','A project valuation includes an unconditional perpetual terminal value despite a fixed uncompensated handover. The main correction is to:',[['Replace the invented residual value with the actual final private rights and obligations.','Vertragsende kann null Erlös und zusätzlich Aufwand bedeuten.'],['Increase the terminal multiple because the asset remains useful to society.','Öffentlicher Nutzen schafft keine zusätzliche private Zahlung.'],['Remove every operating receipt before handover.','Diese ausdrücklich berechtigten Zahlungen bleiben relevant.']],['Bewertet wird der gehaltene Anspruch, nicht ein unbegrenzt unterstellter Eigentumstitel.'],'concession'),
 q('78','d','A stress test raises both project financing costs and renewal expenditure while receipts are capped. It most directly examines:',[['Cash-flow and funding pressures that can occur together.','Gedeckelte Einnahmen können mehrere gleichzeitige Belastungen nicht automatisch auffangen.'],['Only historical reported correlation.','Der Test verändert konkrete wirtschaftliche Mechanismen.'],['A guaranteed proportional increase in equity distributions.','Die bezeichneten Mehrkosten können Ausschüttungen gerade vermindern.']],['Gemeinsame Stressannahmen ergänzen die Betrachtung einzelner Risiken.'],'stress'),
 q('79','d','Two projects have equal expected annual distributions, but one has substantial contingent capital calls. The most appropriate comparison:',[['Includes those additional possible contributions and their timing.','Ausschüttungsprofil allein erfasst die gesamte Anlegerzahlung nicht.'],['Treats the projects as equivalent because distributions match.','Der Anfangs- und Nachschussbedarf kann verschieden sein.'],['Adds capital calls as investor receipts.','Ein Abruf ist aus Anlegersicht eine Auszahlung.']],['Alle Ein- und Auszahlungen gehören in die Anleger- und Liquiditätsanalyse.'],'portfolio'),
 q('80','d','A project has sound operating cash but a large loan maturing during a weak credit market. The analyst should examine:',[['Refinancing needs and the available sources of repayment.','Heute laufendes Cash ersetzt nicht automatisch die fällige Hauptforderung.'],['Only whether this year’s revenue exceeded last year’s.','Umsatzwachstum beantwortet die Fälligkeitsfinanzierung nicht.'],['An automatic refinancing at the original terms.','Neue Kreditbedingungen und Verfügbarkeit sind nicht zugesichert.']],['Betriebstragfähigkeit und Finanzierungslaufzeit können unterschiedliche Engpässe erzeugen.'],'workflow'),
 Q("rea-exam-a1",
   "real-assets",
   "alternatives",
   "mock-a",
   "a",
   "A logistics fund owns six buildings, all leased to the same retailer, and reports annual appraisals. Which additional analysis is most relevant before claiming low risk?",
   [["The common tenant’s credit and the timeliness and realizability of appraised values.","Mehrere Gebäude und glatte NAVs beseitigen weder gemeinsamen Schuldner noch Bewertungsrisiko."],["The separate legal titles as evidence that tenant-credit exposure is diversified across the six buildings.","Sechs Grundstücke verteilen bauliche und örtliche Einzelrisiken, teilen hier aber denselben Mietschuldner. Dessen wirtschaftliches Ausfallrisiko wird nicht durch sechs Eigentumstitel unabhängig."],["The smoothness of the annual appraised NAV as evidence of low loss risk in a prompt liquidation.","Seltene oder geglättete Schätzwerte können beobachtete Schwankungen reduzieren. Daraus folgen weder ein ausführbarer Verkaufspreis noch geringe Verluste bei einem kurzfristigen Verkauf."]],
   0,
   ["Mieter-, Bewertungs- und Liquiditätsrisiko werden gemeinsam beurteilt."],
   {"section":"property-limits"}),
 n('exam-a2','c','A project regulator hypothetically permits a capital-return component of 7% on approved base 160. Actual invested capital is 200. This component relative to actual investment is:',[['5.60%.','11,2 erlaubter Betrag relativ zu 200 tatsächlichem Einsatz.'],['7.00%.','Das ersetzt die tatsächliche durch die anerkannte Basis.'],['8.75%.','Das verwendet den umgekehrten Basisfaktor.']],'Z=100[0{,}07(160)/200]=5{,}6','Der Baustein ist ohne die übrigen Zahlungen noch keine Gesamt- oder Eigenkapital-IRR.','regulated','Isolierter erlaubter Kapitalertrag relativ zum tatsächlichen Einsatz, Prozent.','mock-a'),
 n('exam-b1','b','An asset costs 1500, first-year NOI is 90 and recurring capex is 20% of NOI. Available cash then grows perpetually at 1%. With no debt or other costs, a consistent constant-growth required return is:',[['5.80%.','72 verfügbarer Cashflow durch 1500 plus ein Prozent Wachstum.'],['7.00%.','Das ignoriert Capex im NOI-Zähler.'],['4.80%.','Das ist nur anfängliche Cashrendite ohne Wachstum.']],'Z=100[0{,}8(90)/1500+0{,}01]=5{,}8','Die Renditeforderung muss zur verfügbaren nächsten Cashflowbasis und ewigen Wachstumsannahme passen.','growth-return','Konsistente jährliche Rendite nach den bezeichneten Annahmen, Prozent.','mock-b'),
 n('exam-b2','d','A concession pays 18 at each year end from year 1 through year 8, with no terminal compensation. Initial cost is 60 and discount is 6%. Construction is delayed two years, while the original year-8 expiry remains fixed. With no extra costs, NPV is closest to:',[['18.775221.','Es bleiben sechs Zahlungen in Jahren drei bis acht.'],['51.776289.','Das ignoriert den Ausfall der ersten beiden Zahlungen.'],['39.480499.','Das verschiebt alle acht Zahlungen nach hinten und erfindet Jahre neun und zehn.']],'Z=-60+\\sum_{t=3}^{8}18/(1{,}06)^t\\approx18{,}775221','Ein festes Ende reduziert die Zahl erlaubter Zahlungen; eine reine Zeitverschiebung wäre ein anderer Vertrag.','delay','Kapitalwert bei zwei Jahren Verzug und unverändertem Vertragsende, WE.','mock-b')
];
